    name=&quot;email&quot;
    autocomplete=&quot;email&quot;
    value=&quot;name.example.com&quot;
    aria-invalid=&quot;true&quot;
    aria-describedby=&quot;email-hint email-error&quot;
    aria-errormessage=&quot;email-error&quot;
  /&gt;
&lt;/div&gt;
</code></pre>
    </article>
    <article class="recipe" aria-labelledby="field-with-validity">
        <h2 id="field-with-validity">Field: native validity</h2>
        <p>Uses <a href="/components/field/">field</a>, <a href="/components/label/">label</a>, <a href="/components/text-input/">text-input</a>, <a href="/components/hint/">hint</a>, <a href="/components/error-message/">error-message</a>. Tags: form, validation. <a href="https://github.com/LilyDesignSystem/lily-design-system/blob/main/recipes/field/with-validity.html">Source</a>.</p>
        <!-- A scrolling code block must be reachable by keyboard (axe scrollable-region-focusable). -->
        <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
        <pre tabindex="0" aria-label="Field: native validity markup"><code>&lt;!-- The browser checks the pattern; a theme styles :user-invalid, which matches only after the user has edited and left
     the field. On submit, script shows the error message in the consumer&#x27;s words and adds its id to aria-describedby:
     a hidden element named in aria-describedby is still read out, so it is linked only once it is shown. --&gt;
&lt;div
  class=&quot;field&quot;
  data-required=&quot;true&quot;
&gt;
  &lt;label
    class=&quot;label&quot;
    for=&quot;postcode&quot;
    &gt;Postcode&lt;/label
  &gt;
  &lt;p
    class=&quot;hint&quot;
    id=&quot;postcode-hint&quot;
  &gt;
    For example, LS1 4AP.
  &lt;/p&gt;
  &lt;p
    class=&quot;error-message&quot;
    id=&quot;postcode-error&quot;
    hidden
  &gt;
    Enter a real postcode
  &lt;/p&gt;
  &lt;input
    class=&quot;text-input&quot;
    type=&quot;text&quot;
    id=&quot;postcode&quot;
    name=&quot;postcode&quot;
    autocomplete=&quot;postal-code&quot;
    required
    pattern=&quot;[A-Za-z0-9 ]&#123;5,8&#125;&quot;
    aria-describedby=&quot;postcode-hint&quot;
  /&gt;
&lt;/div&gt;
</code></pre>
    </article>
    <article class="recipe" aria-labelledby="form-complete-form">
        <h2 id="form-complete-form">Form: a complete form</h2>
        <p>Uses <a href="/components/form/">form</a>, <a href="/components/error-summary/">error-summary</a>, <a href="/components/field/">field</a>, <a href="/components/label/">label</a>, <a href="/components/text-input/">text-input</a>, <a href="/components/error-message/">error-message</a>, <a href="/components/radio-group/">radio-group</a>, <a href="/components/radio-input/">radio-input</a>, <a href="/components/button/">button</a>. Tags: form, validation. <a href="https://github.com/LilyDesignSystem/lily-design-system/blob/main/recipes/form/complete-form.html">Source</a>.</p>
        <!-- A scrolling code block must be reachable by keyboard (axe scrollable-region-focusable). -->
        <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
        <pre tabindex="0" aria-label="Form: a complete form markup"><code>&lt;!-- On submit with errors: show the summary, link each item to its field, and move focus to the summary. --&gt;
&lt;form
  class=&quot;form&quot;
  novalidate
  aria-labelledby=&quot;booking-title&quot;
&gt;
  &lt;h2 id=&quot;booking-title&quot;&gt;Book an appointment&lt;/h2&gt;
  &lt;div
    class=&quot;error-summary&quot;
    role=&quot;alert&quot;
    aria-labelledby=&quot;booking-errors&quot;
    tabindex=&quot;-1&quot;
  &gt;
    &lt;h2 id=&quot;booking-errors&quot;&gt;There is a problem&lt;/h2&gt;
    &lt;ul&gt;
      &lt;li&gt;&lt;a href=&quot;#booking-name&quot;&gt;Enter your full name&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
  &lt;/div&gt;
  &lt;div
    class=&quot;field&quot;
    data-required=&quot;true&quot;
    data-invalid=&quot;true&quot;
  &gt;
    &lt;label
      class=&quot;label&quot;
      for=&quot;booking-name&quot;
      &gt;Full name&lt;/label
    &gt;
    &lt;p
      class=&quot;error-message&quot;
      id=&quot;booking-name-error&quot;
    &gt;
      Enter your full name
    &lt;/p&gt;
    &lt;input
      class=&quot;text-input&quot;
      type=&quot;text&quot;
      id=&quot;booking-name&quot;
      name=&quot;name&quot;
      autocomplete=&quot;name&quot;
      required
      aria-invalid=&quot;true&quot;
      aria-describedby=&quot;booking-name-error&quot;
      aria-errormessage=&quot;booking-name-error&quot;
    /&gt;
  &lt;/div&gt;
  &lt;fieldset
    class=&quot;radio-group&quot;
    role=&quot;radiogroup&quot;
    aria-labelledby=&quot;booking-time-legend&quot;
  &gt;
    &lt;legend id=&quot;booking-time-legend&quot;&gt;Preferred time&lt;/legend&gt;
    &lt;input
      class=&quot;radio-input&quot;
      type=&quot;radio&quot;
      id=&quot;booking-morning&quot;
      name=&quot;time&quot;
      value=&quot;morning&quot;
    /&gt;
    &lt;label
      class=&quot;label&quot;
      for=&quot;booking-morning&quot;
      &gt;Morning&lt;/label
    &gt;
    &lt;input
      class=&quot;radio-input&quot;
      type=&quot;radio&quot;
      id=&quot;booking-afternoon&quot;
      name=&quot;time&quot;
      value=&quot;afternoon&quot;
    /&gt;
    &lt;label
      class=&quot;label&quot;
      for=&quot;booking-afternoon&quot;
      &gt;Afternoon&lt;/label
    &gt;
  &lt;/fieldset&gt;
  &lt;button
    class=&quot;button&quot;
    type=&quot;submit&quot;
  &gt;
    Book appointment
  &lt;/button&gt;
&lt;/form&gt;
</code></pre>
    </article>
    <article class="recipe" aria-labelledby="radio-group-conditional-question">
        <h2 id="radio-group-conditional-question">Radio group: a follow-up question shown for one answer</h2>
        <p>Uses <a href="/components/radio-group/">radio-group</a>, <a href="/components/radio-input/">radio-input</a>, <a href="/components/label/">label</a>, <a href="/components/field/">field</a>, <a href="/components/hint/">hint</a>, <a href="/components/text-input/">text-input</a>. Tags: form, choice, conditional. <a href="https://github.com/LilyDesignSystem/lily-design-system/blob/main/recipes/radio-group/conditional-question.html">Source</a>.</p>
        <!-- A scrolling code block must be reachable by keyboard (axe scrollable-region-focusable). -->
        <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
        <pre tabindex="0" aria-label="Radio group: a follow-up question shown for one answer markup"><code>&lt;!-- A conditional question: the follow-up is asked only when &quot;Yes&quot; is chosen. It sits straight after the &quot;Yes&quot; label, inside the
     group, so it is read and tabbed to next. Toggle it with the hidden attribute, never by removing the radio group&#x27;s own
     controls. Keep it to one simple question (GOV.UK&#x27;s research: complicated reveals confused testers); a second question with
     its own reveal belongs on its own page. When the answer changes back to &quot;No&quot; or &quot;Not sure&quot;, the follow-up is hidden: leave
     its answer out when you save, so a hidden answer is never sent. Offer &quot;Not sure&quot; where a person may not know. --&gt;
&lt;fieldset
  class=&quot;radio-group&quot;
  role=&quot;radiogroup&quot;
  aria-labelledby=&quot;anticoagulant-legend&quot;
&gt;
  &lt;legend id=&quot;anticoagulant-legend&quot;&gt;Do you take medicine to thin your blood?&lt;/legend&gt;
  &lt;input
    class=&quot;radio-input&quot;
    type=&quot;radio&quot;
    id=&quot;anticoagulant-yes&quot;
    name=&quot;anticoagulant&quot;
    value=&quot;yes&quot;
    checked
  /&gt;
  &lt;label
    class=&quot;label&quot;
    for=&quot;anticoagulant-yes&quot;
    &gt;Yes&lt;/label
  &gt;
  &lt;div class=&quot;field&quot;&gt;
    &lt;label
      class=&quot;label&quot;
      for=&quot;anticoagulant-name&quot;
      &gt;Which medicine?&lt;/label
    &gt;
    &lt;p
      class=&quot;hint&quot;
      id=&quot;anticoagulant-name-hint&quot;
    &gt;
      For example, warfarin or apixaban
    &lt;/p&gt;
    &lt;input
      class=&quot;text-input&quot;
      type=&quot;text&quot;
      id=&quot;anticoagulant-name&quot;
      name=&quot;anticoagulant-name&quot;
      aria-describedby=&quot;anticoagulant-name-hint&quot;
    /&gt;
  &lt;/div&gt;
  &lt;input
    class=&quot;radio-input&quot;
    type=&quot;radio&quot;
    id=&quot;anticoagulant-no&quot;
    name=&quot;anticoagulant&quot;
    value=&quot;no&quot;
  /&gt;
  &lt;label
    class=&quot;label&quot;
    for=&quot;anticoagulant-no&quot;
    &gt;No&lt;/label
  &gt;
  &lt;input
    class=&quot;radio-input&quot;
    type=&quot;radio&quot;
    id=&quot;anticoagulant-not-sure&quot;
    name=&quot;anticoagulant&quot;
    value=&quot;not-sure&quot;
  /&gt;
  &lt;label
    class=&quot;label&quot;
    for=&quot;anticoagulant-not-sure&quot;
    &gt;Not sure&lt;/label
  &gt;
&lt;/fieldset&gt;
</code></pre>
    </article>
    <article class="recipe" aria-labelledby="radio-group-one-choice">
